"""Original large-vessel vasculitis questions."""
from qbank_authoring import question,ref
rows=[]
V=ref('ACR/Vasculitis Foundation GCA and Takayasu guideline: 2021','https://doi.org/10.1002/acr.24632')
IM=ref('EULAR large-vessel vasculitis imaging: 2023 update','https://ard.bmj.com/content/83/6/741')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A 73-year-old woman has a new temporal headache, jaw claudication, scalp tenderness and transient monocular visual loss. Which diagnosis is most urgent to address?', 'Giant cell arteritis',[
 ('Migraine with aura','New onset at this age with jaw claudication and ischemic visual symptoms requires a different urgent assessment.'),('Trigeminal neuralgia','Brief electric facial pain does not explain the vascular constitutional pattern.'),('Temporomandibular joint osteoarthritis','This can cause jaw pain but does not explain the full ischemic syndrome.')],
 'Recognize cranial ischemia in an older adult','**Jaw claudication and transient visual loss strongly raise concern for GCA.**',['Untreated disease can cause irreversible visual loss.','Inflammatory markers support assessment but cannot safely replace clinical judgment.'], '**Arrange urgent treatment and diagnostic confirmation.**',['Do not delay treatment for biopsy or imaging when ischemia is suspected.','Assess both cranial and extracranial vascular involvement.'],[['Age/new headache','Raises suspicion'],['Jaw claudication','Ischemic clue'],['Visual symptoms','Emergency']],[V,IM],style='clinical_scenario')

q('A patient with strongly suspected GCA has threatened visual loss. Which immediate strategy is most appropriate?', 'Urgent high-dose glucocorticoid treatment, with IV pulse therapy considered for threatened vision, while arranging confirmation',[
 ('Wait for temporal artery biopsy before starting any treatment','Diagnostic delay can expose the other eye to irreversible ischemia.'),('Use low-dose aspirin alone as definitive treatment','Antiplatelet therapy does not adequately suppress the arterial inflammation.'),('Use a slow methotrexate-only induction','This is inadequate immediate protection for threatened vision.')],
 'Protect vision before completing every diagnostic step','**Cranial ischemia makes treatment time-sensitive.**',['IV pulse glucocorticoids are conditionally recommended in the threatened-vision setting.','Diagnostic testing should still be obtained promptly because treatment can reduce some imaging signals.'], '**Coordinate emergency ophthalmic and rheumatological care.**',['Document symptoms, examination and baseline markers.','Plan a subsequent taper and steroid-sparing strategy rather than indefinite high-dose exposure.'],[['Threatened vision','Urgent intensive therapy'],['Confirmation','Prompt but not a reason to delay'],['Long-term care','Relapse and toxicity prevention']],[V],style='clinical_scenario')

q('Under the EULAR 2023 imaging recommendations, what is the preferred first imaging test for suspected GCA when appropriate expertise is promptly available?', 'Ultrasound of temporal and axillary arteries',[
 ('Plain skull radiography','This does not assess the arterial inflammatory process.'),('Routine carotid angiography as the sole first test','It does not provide the recommended initial assessment of mural inflammation.'),('A noncontrast brain CT as the definitive GCA test','It may answer other emergency questions but does not establish or exclude GCA.')],
 'State the guideline and expertise assumptions','**EULAR favors ultrasound including temporal and axillary vessels as first-line imaging.**',['The halo and other mural findings require trained acquisition and interpretation.','The 2021 ACR/VF approach favored temporal biopsy over ultrasound in its local expertise context.'], '**Do not turn a context-specific pathway into a universal exclusion rule.**',['MRI or FDG-PET may be useful alternatives or complements.','Treatment for strongly suspected ischemic disease must not wait for access to a preferred test.'],[['EULAR imaging','Ultrasound first where expert access exists'],['ACR/VF 2021','Biopsy preference in its context'],['Urgent ischemia','Treat without diagnostic delay']],[IM,V])

q('A temporal artery biopsy is negative in a patient with a convincing GCA phenotype. Which interpretation is correct?', 'A negative biopsy does not exclude GCA because of sampling limitations and extracranial disease',[
 ('GCA is definitively excluded regardless of the rest of the assessment','Segmental lesions and sampling issues can reduce sensitivity.'),('The patient must have primary migraine','A negative sample does not establish an alternative diagnosis.'),('All vascular imaging is now unnecessary','Imaging can assess cranial or extracranial disease and alternative explanations.')],
 'Interpret pathology within the whole probability assessment','**GCA can be segmental, and some disease is predominantly extracranial.**',['Adequate specimen length and processing matter.','Use clinical findings and appropriate vascular imaging to resolve persistent uncertainty.'], '**Reassess both supportive evidence and mimics.**',['Do not continue risky treatment indefinitely without a reasoned diagnosis.','Do not stop necessary protection solely because one sample is negative.'],[['Biopsy positive','Strong supporting evidence'],['Biopsy negative','Sensitivity is incomplete'],['Further assessment','Clinical probability plus imaging']],[V,IM],style='clinical_scenario')

q('Which later vascular complication should be considered in GCA follow-up?', 'Aortic aneurysm or stenotic disease at involved sites',[
 ('Congenital coarctation newly caused by the biopsy','This is not an acquired consequence of the procedure or disease.'),('Isolated coronary vasospasm as the only relevant vascular outcome','GCA can involve the aorta and its branches.'),('Venous varicosities as the defining aortic complication','These are anatomically and mechanistically different.')],
 'GCA is not confined to the temporal artery','**Large-vessel inflammation can leave structural vascular damage.**',['Baseline and subsequent imaging are tailored to involvement and clinical circumstances.','Inflammatory control and damage surveillance are related but different tasks.'], '**Investigate new limb claudication, pulse changes or concerning chest/back symptoms.**',['Coordinate vascular expertise for significant damage.','A normal CRP does not exclude an aneurysm or fixed stenosis.'],[['Inflammation','Active mural disease'],['Damage','Stenosis/aneurysm'],['Follow-up','Risk- and involvement-directed']],[V,IM])

q('A GCA patient on tocilizumab has new limb claudication but a normal CRP. Which interpretation is best?', 'IL-6 blockade can suppress CRP; clinical and imaging assessment may still reveal active disease or structural damage',[
 ('Normal CRP excludes both relapse and vascular stenosis','It cannot provide that guarantee, particularly under IL-6 blockade.'),('The symptom proves a drug allergy','The vascular symptom needs assessment rather than an automatic allergy label.'),('The only useful next test is repeat ANA','ANA does not define the arterial process.')],
 'Biomarker suppression changes follow-up interpretation','**Tocilizumab reduces the acute-phase response, which can mask biochemical activity.**',['New ischemic symptoms require vascular assessment.','Fixed damage can also produce symptoms despite controlled inflammation.'], '**Use the clinical pattern and targeted imaging.**',['Review pulses, bilateral pressures and functional impact.','Avoid escalating or withdrawing treatment solely from CRP.'],[['CRP','Can be pharmacologically suppressed'],['Claudication','Active disease or damage'],['Imaging','Can clarify the mechanism']],[V,IM],style='clinical_scenario')

q('Which targeted pathway is inhibited by upadacitinib, approved in the US for adult GCA in 2025?', 'Janus kinase signaling',[
 ('CD20 B-cell depletion','This is the mechanism of rituximab and obinutuzumab.'),('IL-6 receptor binding','This is the mechanism of tocilizumab.'),('Complement C5 cleavage','This is targeted by agents such as eculizumab.')],
 'Recognize a newer GCA treatment without ignoring class risks','**Upadacitinib is a JAK inhibitor with a US adult GCA indication.**',['It is not interchangeable with every other JAK inhibitor for every indication.','Infection, cardiovascular, malignancy and thrombosis risks remain relevant, especially in older patients.'], '**Choose a steroid-sparing strategy through individual benefit-risk assessment.**',['Review local approvals and current labeling.','New approval does not remove the urgency of treating threatened vision.'],[['Upadacitinib','JAK pathway'],['Tocilizumab','IL-6 receptor'],['Patient factors','Determine suitability']],[ref('FDA adult GCA upadacitinib approval record','https://www.accessdata.fda.gov/scripts/opdlisting/oopd/detailedIndex.cfm?cfgridkey=858021')])

q('A 71-year-old has bilateral shoulder and hip girdle pain, prolonged stiffness, raised inflammatory markers and preserved true muscle strength. CK is normal. Which diagnosis best fits?', 'Polymyalgia rheumatica',[
 ('Immune-mediated necrotizing myopathy','Objective weakness and marked muscle enzyme elevation would be more characteristic.'),('Myasthenia gravis','Fatigable ocular/bulbar or motor weakness does not best explain this pain-stiffness syndrome.'),('Inclusion body myositis','The slow finger-flexor/quadriceps weakness pattern is different.')],
 'Separate pain-limited movement from a primary muscle weakness syndrome','**PMR causes proximal girdle pain and stiffness rather than the typical muscle injury of myositis.**',['Exclude mimics, especially when the presentation or treatment response is atypical.','GCA can coexist and must be screened for clinically.'], '**Ask about headache, jaw claudication and visual symptoms.**',['Those findings change urgency and treatment intensity.','A steroid response alone is not uniquely diagnostic of PMR.'],[['PMR','Pain/stiffness'],['Myositis','Objective weakness and muscle injury'],['GCA symptoms','Urgent parallel assessment']],[V],style='clinical_scenario')

q('A 28-year-old woman has arm claudication, unequal brachial pressures, diminished radial pulse and a subclavian bruit. Which diagnosis is most likely?', 'Takayasu arteritis',[
 ('Giant cell arteritis','The age and arterial pattern favor Takayasu, though both are large-vessel vasculitides.'),('Buerger disease','This is a different tobacco-associated distal thrombo-occlusive disease.'),('Microscopic polyangiitis','Small-vessel pauci-immune disease does not typically cause this aortic-branch pattern.')],
 'Recognize aortic-branch disease in a younger patient','**Takayasu arteritis can produce stenoses, bruits, pulse loss and pressure asymmetry.**',['The aorta, renal and other branches may be affected.','Constitutional inflammation can precede obvious occlusive signs.'], '**Image the relevant arterial tree and assess organ perfusion.**',['Check blood pressure using a reliably perfused limb.','Evaluate renal, cardiac, neurological and ocular consequences.'],[['Claudication/pulse loss','Arterial obstruction'],['Young adult','Supports Takayasu context'],['Imaging','Defines extent and activity/damage']],[V,IM],style='clinical_scenario')

q('Which imaging method is favored by EULAR for evaluating suspected Takayasu arteritis when suitable?', 'MRI/MR angiography',[
 ('Plain chest radiography alone','It cannot adequately characterize the arterial wall and lumen.'),('Temporal artery ultrasound alone','This does not map the typical aortic and branch distribution of Takayasu.'),('Renal scintigraphy alone','This does not define the systemic large-vessel disease.')],
 'Assess wall inflammation and luminal damage','**MRI is a preferred modality for Takayasu assessment in appropriate settings.**',['CT angiography, FDG-PET and ultrasound can be alternatives or complements depending on the question and access.','Luminal stenosis does not by itself prove ongoing active inflammation.'], '**Choose imaging for the clinical decision.**',['Follow structural lesions and new symptoms with a consistent appropriate method.','Balance radiation, contrast exposure and feasibility.'],[['MRI/MRA','Wall/lumen assessment without ionizing radiation'],['CTA','High-resolution anatomy'],['PET','Metabolic inflammation context']],[IM])

q('A Takayasu patient has severe left subclavian stenosis. Left-arm BP is 90/60 but the right arm is 170/95. What is the best interpretation?', 'The low left-arm reading may underestimate central pressure because of arterial obstruction',[
 ('The lower reading must always be the true systemic pressure','Pressure distal to stenosis can be misleading.'),('The higher reading must be discarded solely because it differs','A reliably perfused site is needed for systemic BP assessment.'),('No hypertension assessment is possible in large-vessel disease','Alternative limbs and vascular assessment can guide monitoring.')],
 'Measure pressure where it reflects systemic perfusion','**A stenosed artery can produce a falsely reassuring low distal BP.**',['Compare limbs and correlate with vascular anatomy.','Unrecognized systemic hypertension can worsen cardiac, renal and vascular injury.'], '**Establish and document a reliable monitoring site.**',['Assess renal artery disease as a possible contributor to hypertension.','Avoid treatment decisions based only on the most easily palpable affected arm.'],[['Distal to stenosis','Pressure may be reduced'],['Reliable limb/site','Needed for systemic monitoring'],['Pressure asymmetry','Clue to arterial disease']],[V],style='clinical_scenario')

q('A Takayasu patient has disabling limb ischemia from a fixed stenosis. When feasible, how should elective revascularization be timed?', 'After inflammatory disease is controlled, with urgent exceptions for threatened organs or limbs',[
 ('During uncontrolled active inflammation in every case','Active disease can worsen procedural outcomes and restenosis risk.'),('Never, because immune treatment always reverses all mature stenoses','Fixed damage may require intervention.'),('Only after all autoantibodies become negative','There is no such universal serological prerequisite.')],
 'Separate inflammatory control from mechanical repair','**Elective vascular intervention is generally more favorable in controlled disease.**',['Critical ischemia can require urgent action despite active inflammation.','The decision needs rheumatological and vascular expertise.'], '**Assess the reason for symptoms and the viability of threatened tissue.**',['Continue an appropriate peri-procedural disease-control plan.','Monitor for restenosis and progression elsewhere.'],[['Active inflammation','Treat immune disease'],['Fixed stenosis','May need repair'],['Threatened organ','Urgent individualized intervention']],[V],style='clinical_scenario')

if __name__=='__main__':print(f'Vasculitis draft: {len(rows)} questions')
